// Usage: node benchmarks/eval/straight-detours.mjs [--json]; needs target/release/layout-command.
// Experimental `straightDetours` (ADR 0020, S1-1b) on the mixed playground examples (generated by benchmarks/generate.py):
// the default, the option, `singlePassMixed`, and both. Prints lines through nodes (shape-aware), crossings, bends, area,
// the straight-edge findings and the time of one import.
import {readFileSync, existsSync} from 'node:fs';
import {arqlet, normalizeArqlet, metrics, ROOT} from './lib.mjs';

const rows = [];
for (const name of ['mixed-large', 'mixed-layouts', 'self-loops', 'can-bus', 'nested-tree-radial', 'petri-net-shapes']) {
  const file = `${ROOT}apps/playground/generated/examples/${name}.json`;
  if (!existsSync(file)) continue;
  const raw = JSON.parse(readFileSync(file, 'utf8'));
  const graph = raw.graph ?? raw;
  for (const [variant, options] of [['default', {}], ['straightDetours', {straightDetours: true}],
    ['singlePassMixed', {singlePassMixed: true}], ['singlePassMixed + straightDetours', {singlePassMixed: true, straightDetours: true}]]) {
    const {snapshot, ms} = arqlet({op: 'import', graph, limit: graph.nodes.length, options});
    const m = metrics(normalizeArqlet(snapshot));
    rows.push({dataset: name, variant, lineNodeHits: m.lineNodeHits, crossings: m.crossings, bends: m.bends,
      areaK: Math.round(m.area / 1e3), straightThroughNode: snapshot.geometryIssues.filter(i => i.kind === 'straight-through-node').length,
      ms: Math.round(ms)});
  }
}
if (process.argv.includes('--json')) for (const r of rows) console.log(JSON.stringify(r));
else {
  console.log('| dataset | variant | line–node hits | crossings | bends | area (k) | straight-through-node | ms |');
  console.log('|---|---|---|---|---|---|---|---|');
  for (const r of rows) console.log(`| ${r.dataset} | ${r.variant} | ${r.lineNodeHits} | ${r.crossings} | ${r.bends} | ${r.areaK} | ${r.straightThroughNode} | ${r.ms} |`);
}
